SELECT p.* FROM payment p



        AND p.integratedpayment_id IN (
            SELECT integratedpayment_id FROM integrated_payment WHERE store_id = #{storeId}
        )


        AND p.users_id = #{usersId}


        AND p.payment_method = #{paymentType}


        AND p.payment_status = #{status}


        AND p.payment_created_at >= #{startDate}


        AND p.payment_created_at <= #{endDate}


        AND p.payment_amount >= #{minAmount}


        AND p.payment_amount <= #{maxAmount}



ORDER BY p.payment_created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT ip.store_id
FROM integrated_payment ip
WHERE ip.integratedpayment_id = #{integratedPaymentId}

SELECT COUNT(*) > 0
FROM review r
WHERE r.users_id = #{userId}
AND r.review_status = 'Y'
AND EXISTS (
    SELECT 1 FROM payment p
    JOIN integrated_payment ip ON p.integratedpayment_id = ip.integratedpayment_id
    WHERE p.payment_id = #{paymentId}
    AND ip.store_id = r.store_id
)
